/// <summary>
/// Retrieves the <c>LedgerDimensionDefaultAccount</c> value that is used for posting duty component COGS.
/// </summary>
/// <returns>
/// The <c>LedgerDimensionDefaultAccount</c> value that is used for posting duty component COGS.
/// </returns>
public LedgerDimensionDefaultAccount METLedgerDimensionLineAccountConsumption()
{
    return salesLine.accountConsumptionLedgerDimension(salesLine.inventTable());
}
